#include <algorithm>
#include <cassert>
#include <climits>
#include <cstddef>
#include <cstdint>
#include <iostream>
#include <sstream>
#include <string>
#include <limits>
#include <stdexcept>
#include <vector>
static_assert(INT_MIN == (-2147483647 - 1) && INT_MAX == 2147483647, "32-bit int required");
std::int64_t smallest_difference(std::vector<int> a, std::vector<int> b) {
    if (a.empty() || b.empty()) throw std::invalid_argument("empty list");
    std::sort(a.begin(), a.end()); std::sort(b.begin(), b.end());
    std::size_t i = 0, j = 0;
    std::int64_t best = std::numeric_limits<std::int64_t>::max();
    while (i < a.size() && j < b.size()) {
        // 뺄셈 전에 넓혀 INT_MIN과 INT_MAX 사이 차이도 보존합니다.
        const std::int64_t d = static_cast<std::int64_t>(a[i]) - static_cast<std::int64_t>(b[j]);
        const std::int64_t distance = d < 0 ? -d : d;
        best = std::min(best, distance);
        if (d == 0) return 0;
        if (d < 0) ++i; else ++j;
    }
    return best;
}
// 정수 하나는 공백으로 나눈 토큰 전체여야 합니다. 1+2를 두 수로 읽지 않습니다.
bool read_integer(std::istream& input, long long& value) {
    std::string token;
    if (!(input >> token)) return false;
    const std::size_t first = (token[0] == '+' || token[0] == '-') ? 1 : 0;
    if (first == token.size()) return false;
    for (std::size_t i = first; i < token.size(); ++i)
        if (token[i] < '0' || token[i] > '9') return false;
    std::istringstream parser(token);
    parser >> value;
    return !parser.fail() && parser.eof();
}

int main(){
 // 입력: n m 뒤에 첫 목록 n개, 둘째 목록 m개. 추가 토큰은 거부합니다.
 long long n=0,m=0;if((!read_integer(std::cin,n)||!read_integer(std::cin,m))||n<1||m<1||n>100000||m>100000)return 1;
 std::vector<int>a,b;
 for(int which=0;which<2;++which){const long long count=which==0?n:m;
  auto&v=which==0?a:b;
  for(long long i=0;i<count;++i){long long x=0;if(!read_integer(std::cin,x)||x<INT_MIN||x>INT_MAX)return 1;v.push_back(static_cast<int>(x));}}
 std::cin>>std::ws;if(std::cin.peek()!=std::char_traits<char>::eof())return 1;
 std::cout<<smallest_difference(a,b)<<'\n';return std::cout?0:1;
}
